    #[test]
    fn ranking() {
        let front = [ip("104.16.1.1")];
        let cands = vec![
            OriginCandidate {
                ip: ip("104.16.1.1"),
                source: OriginSource::Historical("2023".into()),
            },
            OriginCandidate {
                ip: ip("104.17.0.9"),
                source: OriginSource::Subdomain("www.ex.com".into()),
            },
            OriginCandidate {
                ip: ip("10.0.0.5"),
                source: OriginSource::Subdomain("intra.ex.com".into()),
            },
            OriginCandidate {
                ip: ip("5.9.10.10"),
                source: OriginSource::Subdomain("origin.ex.com".into()),
            },
            OriginCandidate {
                ip: ip("5.9.10.10"),
                source: OriginSource::Historical("otx".into()),
            },
            OriginCandidate {
                ip: ip("5.9.10.11"),
                source: OriginSource::Mx("mx.ex.com".into()),
            },
            OriginCandidate {
                ip: ip("81.2.69.50"),
                source: OriginSource::Subdomain("blog.ex.com".into()),
            },
        ];
        let r = rank_origin_candidates(&front, &cands);
        assert_eq!(r.cdn.as_deref(), Some("cloudflare"));
        let order: Vec<String> = r.candidates.iter().map(|c| c.ip.to_string()).collect();
        assert_eq!(order, vec!["5.9.10.10", "5.9.10.11", "81.2.69.50"]);
        let top = &r.candidates[0];
        // 45 + 15 (two kinds) + 10 (hosting) + 5 (same /24)
        assert_eq!(top.score, 75);
        assert!(top.reasons.iter().any(|r| r == "origin_label"));
        assert!(top.reasons.iter().any(|r| r == "multi_source"));
        assert_eq!(top.class.as_ref().unwrap().provider, "hetzner");
        let dropped: BTreeMap<String, &str> = r
            .dropped
            .iter()
            .map(|(i, w)| (i.to_string(), w.as_str()))
            .collect();
        assert_eq!(dropped["104.16.1.1"], "front");
        assert_eq!(dropped["104.17.0.9"], "cdn");
        assert_eq!(dropped["10.0.0.5"], "not_public");
        // not behind a CDN
        assert!(rank_origin_candidates(&[ip("5.9.1.1")], &[]).cdn.is_none());
    }

    #[tokio::test]
    async fn dns_candidates() {
        let z = StaticDns::new()
            .add("ex.com", RType::MX, &["10 mail.ex.com."])
            .add(
                "ex.com",
                RType::TXT,
                &["v=spf1 ip4:203.0.113.7 -all", "google-site-verification=x"],
            )
            .add("mail.ex.com", RType::A, &["203.0.113.7"])
            .add("dev.ex.com", RType::A, &["198.51.100.4"])
            .add("dev.ex.com", RType::AAAA, &["2001:db8::4"]);
        let c = collect_dns_candidates(
            &z,
            "EX.com",
            &["dev.ex.com".into(), "ex.com".into(), "gone.ex.com".into()],
        )
        .await;
        assert_eq!(
            c,
            vec![
                OriginCandidate {
                    ip: ip("203.0.113.7"),
                    source: OriginSource::Mx("mail.ex.com".into())
                },
                OriginCandidate {
                    ip: ip("203.0.113.7"),
                    source: OriginSource::SpfIp
                },
                OriginCandidate {
                    ip: ip("198.51.100.4"),
                    source: OriginSource::Subdomain("dev.ex.com".into())
                },
                OriginCandidate {
                    ip: ip("2001:db8::4"),
                    source: OriginSource::Subdomain("dev.ex.com".into())
                },
            ]
        );
    }
